CREATE TABLE IF NOT EXISTS wallets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,balance DECIMAL(14,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',status ENUM('active','locked') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY wallet_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wallet_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,wallet_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,type ENUM('credit','debit') NOT NULL,category VARCHAR(60) NOT NULL,amount DECIMAL(14,2) NOT NULL, balance_after DECIMAL(14,2) NOT NULL,reference_type VARCHAR(60) NULL,reference_id BIGINT UNSIGNED NULL,description VARCHAR(500) NULL,created_at TIMESTAMP NULL,KEY wallet_ledger_user(user_id,created_at),KEY wallet_ledger_reference(reference_type,reference_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
